cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" roadmap list --focus AJC.picrep --json 2>/dev/null | python3 -c "
import json,sys
items=json.load(sys.stdin)
for it in items:
    print('---')
    print('id:',it.get('id'),'| status:',it.get('status'),'| owner:',repr(it.get('owner')),'| parent:',it.get('parent'),'| milestone:',it.get('milestone'))
    print('title:',it.get('title'))
    s=(it.get('summary') or '').strip()
    if s: print('summary:',s[:1500])
    st=(it.get('strategy') or '').strip()
    if st: print('strategy:',st[:1200])
    for k in ('pinned_commit','pin_commit','anchors','refs'):
        if it.get(k): print(k+':',it[k])
"
